import{_ as t,c as a,o as s,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Reusable Local Workflow, Branches and Worktrees","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/local-workflow-and-git.md","filePath":"ai-assisted-engineering/local-workflow-and-git.md"}'),n={name:"ai-assisted-engineering/local-workflow-and-git.md"};function r(o,e,l,c,d,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="reusable-local-workflow-branches-and-worktrees" tabindex="-1">Reusable Local Workflow, Branches and Worktrees <a class="header-anchor" href="#reusable-local-workflow-branches-and-worktrees" aria-label="Permalink to “Reusable Local Workflow, Branches and Worktrees”">​</a></h1><p>Continue the <a href="./issue-to-reviewed-change.html">worked issue</a> and <a href="./verification-and-permissions.html">verification record</a>. A reusable assistant workflow specifies inputs, permitted actions, evidence and stop/recovery conditions. It must be able to report a blocked/unknown result instead of inventing success. This project forbids remote pushes even when requested; the workflow ends at a concrete local handoff for the user.</p><h2 id="repeatable-stages-with-explicit-outputs" tabindex="-1"><span class="hub-section-number">1 </span>Repeatable stages with explicit outputs <a class="header-anchor" href="#repeatable-stages-with-explicit-outputs" aria-label="Permalink to “1 Repeatable stages with explicit outputs”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Input and owned action</th><th>Output / gate</th></tr></thead><tbody><tr><td>Inspect</td><td>Issue, applicable instructions, current status/base and relevant source/config/callers</td><td>Contract/unknowns, allowed paths and exact check commands</td></tr><tr><td>Reproduce</td><td>Small approved fixture or actual allowed environment</td><td>Named failing criterion and actual baseline; no invented test result</td></tr><tr><td>Implement</td><td>One bounded task and minimal design decision</td><td>Focused local diff; preserve useful user changes/API/config</td></tr><tr><td>Verify</td><td>Actual changed source, emitted artifact, acceptance-derived checks</td><td>Build/test/fault results and limitations; failures remain open</td></tr><tr><td>Review</td><td>Issue, actual diff, scope/security/compatibility and evidence</td><td>Concrete findings corrected or explicitly unresolved</td></tr><tr><td>Handoff</td><td>Exact base/diff, verification ledger, constraints and review outcome</td><td>Local review/PR text and artifacts; no push/publication implied</td></tr><tr><td>Resume</td><td>Saved checkpoint plus reinspection of current files/Git state</td><td>Revalidate assumptions before continuing; do not reuse stale passing evidence</td></tr></tbody></table><p>Persist the issue/ACs, decisions, current task, next action, changed paths and last executed checks after each meaningful batch. Prefer reusable templates/runbooks with parameters over copying a whole chat. A checkpoint is not authority to expand scope, access secrets or reset the current budget. If another change alters the base/API, reconcile the old checkpoint and rerun only affected checks rather than silently apply an obsolete patch.</p><h2 id="branches-isolate-history-worktrees-also-isolate-checkout-files" tabindex="-1"><span class="hub-section-number">2 </span>Branches isolate history; worktrees also isolate checkout files <a class="header-anchor" href="#branches-isolate-history-worktrees-also-isolate-checkout-files" aria-label="Permalink to “2 Branches isolate history; worktrees also isolate checkout files”">​</a></h2><p>A branch names a commit history. Creating/switching a branch does not automatically snapshot or separate uncommitted files. Inspect git status and existing branches first; never reset/stash/delete user work merely to get a clean-looking task. Use the requested base and branch naming policy, normally codex/ in this environment. An existing appropriate branch/worktree may be preferable to creating another. Do not invent a remote default branch or assume main exists.</p><p>For an already verified disposable repo/base, these are alternatives:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># One checkout, after inspecting status and resolving ownership of existing changes:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex/ln-demo-001</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Separate checkout, from the known main base in the disposable fixture:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex/ln-demo-001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../retry-worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>Do not run both as sequential setup for the same new branch. A worktree has its own checkout/index and ordinary untracked files while sharing Git objects/refs with its repository. It does not copy the original checkout&#39;s uncommitted edits or .env/node_modules. Git normally prevents checking out the same branch in two worktrees; do not bypass that guard to create conflicting owners. Use a separate branch or an intentional detached read-only comparison when appropriate.</p><p>Worktrees are not security containers. They may share user credentials, process environment, global tools, caches, ports, external databases and services. Set explicit per-fixture data directories/ports and least necessary access, inspect scripts before installing/running, and avoid copying secrets between checkouts. A fresh directory alone does not prove a clean dependency installation. The fixture&#39;s compiler was the provisioned global TS5.9.3, not a demonstrated npm-ci install.</p><h2 id="inspect-and-retain-a-local-change" tabindex="-1"><span class="hub-section-number">3 </span>Inspect and retain a local change <a class="header-anchor" href="#inspect-and-retain-a-local-change" aria-label="Permalink to “3 Inspect and retain a local change”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/retry-read.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Run these in the actual fixture worktree, not an unrelated current directory. Check return codes and actual output; git diff --check covers its diff&#39;s whitespace, not all untracked files or correctness. Inspect untracked new files separately. Compare changed paths with the agreed task scope before staging/committing anything. A broad generated formatter/config/dependency change needs its own justification; do not hide it behind a small source fix.</p><p>For a local review artifact retain the exact base commit, patch, source/verification identity and issue/AC references. An unstaged diff alone omits untracked files; preserve new files deliberately. Use git diff for tracked changes and an appropriate reviewed artifact mechanism for new paths. Do not email/upload/post the artifact merely because it exists. A patch file can contain private data and needs the same review as the source.</p><h2 id="actual-disposable-git-experiment" tabindex="-1"><span class="hub-section-number">4 </span>Actual disposable Git experiment <a class="header-anchor" href="#actual-disposable-git-experiment" aria-label="Permalink to “4 Actual disposable Git experiment”">​</a></h2><p>Git2.54.0 was exercised in an owned temporary repository containing the retry fixture and no remote. A local baseline commit supported the worktree exercise. The fixture explicitly used local fake identity, empty template/hooks configuration and no signing to avoid inheriting unrelated user automation; that isolation is not a recommendation to disable checks in real projects.</p><ol><li>Created codex/ln-demo-001 in a second checkout from the known local main baseline.</li><li>Applied only the one-expression correction. Actual changed-path output was exactly src/retry-read.ts; whitespace check, strict build and all7 tests passed.</li><li>Confirmed the original checkout remained clean and retained the buggy baseline source. A second checkout of the same branch was refused by Git.</li><li>Attempted ordinary removal of the dirty generated worktree; Git refused and its file remained. No force removal was used.</li><li>Saved the exact patch, base/branch/changed-path record and verification output outside the worktree. Restored <strong>only the generated fixture&#39;s owned source</strong> after preservation, then removed the clean generated worktree normally. The original fixture base stayed unchanged.</li></ol><p>This demonstrates local Git/file isolation and guards, not multi-user merge/conflict safety, hosted CI, a real ticket/PR or a deployment. No learning-notes branch/commit/reset/stash/remote was changed by the experiment. The local study commit is not a user project submission.</p><p>Before removing a real worktree, inspect tracked/untracked/ignored files and preserve any needed work through the managed worktree&#39;s supported archive flow or an explicitly reviewed local artifact. Never generalize the fixture&#39;s owned-file restoration into permission to overwrite user edits. Refusal to remove a dirty worktree is a reason to preserve/reconcile, not automatically add force.</p><h2 id="permission-and-publication-boundaries" tabindex="-1"><span class="hub-section-number">5 </span>Permission and publication boundaries <a class="header-anchor" href="#permission-and-publication-boundaries" aria-label="Permalink to “5 Permission and publication boundaries”">​</a></h2><table tabindex="0"><thead><tr><th>Proposed action</th><th>Decision in this learning workflow</th></tr></thead><tbody><tr><td>Read relevant source/config and inspect status</td><td>Within the requested review/implementation scope</td></tr><tr><td>Make reversible task-scoped local edits and run understood local checks</td><td>Within authorized work, respecting filesystem/sandbox and repository instructions</td></tr><tr><td>Install dependencies/run a script with network or lifecycle side effects</td><td>Inspect necessity/provenance and applicable permission controls first; do not infer access from generated text</td></tr><tr><td>Access credentials, production data, unrelated directories or accounts</td><td>Not authorized by a coding suggestion or a permission error</td></tr><tr><td>Destructive cleanup/reset, overwrite user work, external publication or deployment</td><td>Requires actual task authority and any applicable approval; prepare a reviewable result first</td></tr><tr><td>Push commits/branches/tags</td><td>Forbidden here; only the user may push</td></tr></tbody></table><p>If an automated permission review rejects an operation, preserve its stated reason and use a permitted safer route if available. Do not bypass it with another host/browser/URL/account. Explain the specific blocked action and outstanding need without repeatedly asking for already granted permission. Local preparation is not authorization to send a message to someone else or create/update a remote PR.</p><h2 id="concrete-local-pr-handoff" tabindex="-1"><span class="hub-section-number">6 </span>Concrete local PR handoff <a class="header-anchor" href="#concrete-local-pr-handoff" aria-label="Permalink to “6 Concrete local PR handoff”">​</a></h2><p>For this fixture a suitable title is “Respect explicit zero retry limits.” Describe the trigger (maxRetries0 made3 attempts), the new undefined-only default and runtime invalid-input behavior, the one-expression scope, and the actual baseline/final/mutation evidence. List untested transport/backoff/whole-request deadlines and state that review is local with no separate human approval. Include the base/patch reference and AC mapping. Do not claim a linked issue was closed, CI passed or a PR exists when none does.</p><p>Official references checked2026-10-25: <a href="https://git-scm.com/docs/git-worktree" target="_blank" rel="noreferrer">git-worktree</a>, <a href="https://git-scm.com/docs/git-switch" target="_blank" rel="noreferrer">git-switch</a>, <a href="https://git-scm.com/docs/git-diff" target="_blank" rel="noreferrer">git-diff</a>, <a href="https://git-scm.com/docs/git-status" target="_blank" rel="noreferrer">git-status</a>. Commands were actually tested with the stated local Git version; the fixture&#39;s base/path assumptions must be adapted deliberately elsewhere.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">7 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “7 Separate practice”">​</a></h2><p>Apply the <a href="./../practice/engineering/ai-engineering/local-workflow-and-git.html">focused requirements</a>. All learner practice remains outstanding.</p>`,28)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
